-- ==================================================================
-- Source: database/src/tables/01_foundation/ServiceArea.sql
-- ==================================================================
-- SERVICE_AREA: dining areas (Main dining, Patio, Bar).
-- Level 1: points to nothing.
CREATE TABLE dbo.SERVICE_AREA (
    areaId   INT IDENTITY(1,1) NOT NULL,
    areaName VARCHAR(40)       NOT NULL,

    CONSTRAINT PK_SERVICE_AREA PRIMARY KEY (areaId),
    CONSTRAINT UQ_SERVICE_AREA_areaName UNIQUE (areaName)
);
GO

-- ==================================================================
-- Source: database/src/tables/01_foundation/Course.sql
-- ==================================================================
-- COURSE: lookup of courses (1 Apps, 2 Mains, 3 Dessert).
-- Level 1: points to nothing.
CREATE TABLE dbo.COURSE (
    courseId     INT IDENTITY(1,1) NOT NULL,
    courseNumber INT               NOT NULL,
    courseName   VARCHAR(20)       NOT NULL,

    CONSTRAINT PK_COURSE PRIMARY KEY (courseId),
    CONSTRAINT UQ_COURSE_courseNumber UNIQUE (courseNumber),
    CONSTRAINT CK_COURSE_courseNumber CHECK (courseNumber > 0)
);
GO

-- ==================================================================
-- Source: database/src/tables/01_foundation/Employee.sql
-- ==================================================================
-- EMPLOYEE: supertype of SERVER and MANAGER.
-- Hierarchy: overlapping (one person can be both), partial (hosts are neither).
-- isServer / isManager are the discriminator flags; they must match the
-- subtype rows (checked by tests/04_foundation_menu_checks.sql).
-- Level 1: points to nothing.
CREATE TABLE dbo.EMPLOYEE (
    employeeId INT IDENTITY(1,1) NOT NULL,
    firstName  VARCHAR(40)       NOT NULL,
    lastName   VARCHAR(40)       NOT NULL,
    posPin     CHAR(4)           NOT NULL,
    hireDate   DATE              NOT NULL,
    isServer   BIT               NOT NULL CONSTRAINT DF_EMPLOYEE_isServer  DEFAULT (0),
    isManager  BIT               NOT NULL CONSTRAINT DF_EMPLOYEE_isManager DEFAULT (0),

    CONSTRAINT PK_EMPLOYEE PRIMARY KEY (employeeId),
    CONSTRAINT UQ_EMPLOYEE_posPin UNIQUE (posPin),
    -- Exactly four digits (CHAR pads short values with spaces, which fail this).
    CONSTRAINT CK_EMPLOYEE_posPin CHECK (posPin NOT LIKE '%[^0-9]%')
);
GO

-- ==================================================================
-- Source: database/src/tables/01_foundation/DiningTable.sql
-- ==================================================================
-- DINING_TABLE: physical tables on the floor.
-- Level 2: points to SERVICE_AREA.
CREATE TABLE dbo.DINING_TABLE (
    tableId      INT IDENTITY(1,1) NOT NULL,
    areaId       INT               NOT NULL,
    tableNumber  INT               NOT NULL,
    seatCapacity INT               NOT NULL,

    CONSTRAINT PK_DINING_TABLE PRIMARY KEY (tableId),
    CONSTRAINT FK_DINING_TABLE_SERVICE_AREA
        FOREIGN KEY (areaId) REFERENCES dbo.SERVICE_AREA (areaId),
    CONSTRAINT UQ_DINING_TABLE_tableNumber UNIQUE (tableNumber),
    CONSTRAINT CK_DINING_TABLE_tableNumber CHECK (tableNumber > 0),
    CONSTRAINT CK_DINING_TABLE_seatCapacity CHECK (seatCapacity > 0)
);
GO

-- ==================================================================
-- Source: database/src/tables/01_foundation/Server.sql
-- ==================================================================
-- SERVER: subtype of EMPLOYEE (employees who take tables).
-- Level 2: points to EMPLOYEE.
CREATE TABLE dbo.SERVER (
    employeeId INT        NOT NULL,
    serverCode VARCHAR(4) NOT NULL,

    CONSTRAINT PK_SERVER PRIMARY KEY (employeeId),
    CONSTRAINT FK_SERVER_EMPLOYEE
        FOREIGN KEY (employeeId) REFERENCES dbo.EMPLOYEE (employeeId),
    CONSTRAINT UQ_SERVER_serverCode UNIQUE (serverCode)
);
GO

-- ==================================================================
-- Source: database/src/tables/01_foundation/Manager.sql
-- ==================================================================
-- MANAGER: subtype of EMPLOYEE (approves voids and overrides).
-- Level 2: points to EMPLOYEE.
CREATE TABLE dbo.MANAGER (
    employeeId   INT     NOT NULL,
    overrideCode CHAR(6) NOT NULL,

    CONSTRAINT PK_MANAGER PRIMARY KEY (employeeId),
    CONSTRAINT FK_MANAGER_EMPLOYEE
        FOREIGN KEY (employeeId) REFERENCES dbo.EMPLOYEE (employeeId),
    CONSTRAINT UQ_MANAGER_overrideCode UNIQUE (overrideCode),
    CONSTRAINT CK_MANAGER_overrideCode CHECK (overrideCode NOT LIKE '%[^0-9]%')
);
GO

-- ==================================================================
-- Source: database/src/tables/01_foundation/Shift.sql
-- ==================================================================
-- SHIFT: a service period (Brunch, Dinner).
-- Only one shift may be open at a time: see src/indexes/02_ux_shift_single_open.sql.
-- Level 2: points to EMPLOYEE (who closed it).
CREATE TABLE dbo.SHIFT (
    shiftId            INT IDENTITY(1,1) NOT NULL,
    shiftName          VARCHAR(20)       NOT NULL,
    businessDate       DATE              NOT NULL,
    openedAt           DATETIME          NOT NULL,
    closedAt           DATETIME          NULL,
    closedByEmployeeId INT               NULL,

    CONSTRAINT PK_SHIFT PRIMARY KEY (shiftId),
    CONSTRAINT FK_SHIFT_EMPLOYEE
        FOREIGN KEY (closedByEmployeeId) REFERENCES dbo.EMPLOYEE (employeeId),
    -- A closed shift records both when and by whom; an open shift has neither.
    CONSTRAINT CK_SHIFT_closed_together CHECK (
        (closedAt IS NULL AND closedByEmployeeId IS NULL)
        OR (closedAt IS NOT NULL AND closedByEmployeeId IS NOT NULL)
    ),
    CONSTRAINT CK_SHIFT_closedAt_after_openedAt CHECK (closedAt IS NULL OR closedAt >= openedAt)
);
GO

-- ==================================================================
-- Source: database/src/tables/02_menu/MenuEntry.sql
-- ==================================================================
-- MENU_ENTRY: supertype of CATEGORY, MENU_ITEM and ADD_ON; one node of the menu tree.
-- Hierarchy: disjoint, total, discriminator entryType (C category, I item, A add-on).
-- parentEntryId is the recursive "parent of" relationship. Only the root has no parent:
-- see src/indexes/01_ux_menu_entry_single_root.sql.
-- Which types may sit under which (items under categories, add-ons under items) is
-- enforced by the MenuTree and checked by tests/04_foundation_menu_checks.sql.
-- Level 2: points to itself.
CREATE TABLE dbo.MENU_ENTRY (
    entryId       INT IDENTITY(1,1) NOT NULL,
    parentEntryId INT               NULL,
    entryName     VARCHAR(60)       NOT NULL,
    entryType     CHAR(1)           NOT NULL,
    displayOrder  INT               NOT NULL,

    CONSTRAINT PK_MENU_ENTRY PRIMARY KEY (entryId),
    CONSTRAINT FK_MENU_ENTRY_parent
        FOREIGN KEY (parentEntryId) REFERENCES dbo.MENU_ENTRY (entryId),
    -- Siblings can't share a display position.
    CONSTRAINT UQ_MENU_ENTRY_sibling_order UNIQUE (parentEntryId, displayOrder),
    CONSTRAINT CK_MENU_ENTRY_entryType CHECK (entryType IN ('C', 'I', 'A')),
    -- Only a category can be the root.
    CONSTRAINT CK_MENU_ENTRY_root_is_category CHECK (parentEntryId IS NOT NULL OR entryType = 'C'),
    CONSTRAINT CK_MENU_ENTRY_not_own_parent CHECK (parentEntryId IS NULL OR parentEntryId <> entryId),
    CONSTRAINT CK_MENU_ENTRY_displayOrder CHECK (displayOrder > 0)
);
GO

-- ==================================================================
-- Source: database/src/tables/02_menu/Category.sql
-- ==================================================================
-- CATEGORY: subtype of MENU_ENTRY (menus and groups, e.g. Food, Burgers).
-- availableFrom / availableTo limit a group to certain hours (e.g. brunch only).
-- Level 3: points to MENU_ENTRY.
CREATE TABLE dbo.CATEGORY (
    entryId       INT  NOT NULL,
    availableFrom TIME NULL,
    availableTo   TIME NULL,

    CONSTRAINT PK_CATEGORY PRIMARY KEY (entryId),
    CONSTRAINT FK_CATEGORY_MENU_ENTRY
        FOREIGN KEY (entryId) REFERENCES dbo.MENU_ENTRY (entryId),
    -- Hours are given as a pair or not at all.
    CONSTRAINT CK_CATEGORY_hours_together CHECK (
        (availableFrom IS NULL AND availableTo IS NULL)
        OR (availableFrom IS NOT NULL AND availableTo IS NOT NULL)
    ),
    CONSTRAINT CK_CATEGORY_hours_order CHECK (availableFrom IS NULL OR availableFrom < availableTo)
);
GO

-- ==================================================================
-- Source: database/src/tables/02_menu/MenuItem.sql
-- ==================================================================
-- MENU_ITEM: subtype of MENU_ENTRY (something a guest orders).
-- defaultCourseId is the course the item usually goes in; NULL for drinks.
-- Level 3: points to MENU_ENTRY and COURSE.
CREATE TABLE dbo.MENU_ITEM (
    entryId         INT          NOT NULL,
    basePrice       DECIMAL(8,2) NOT NULL,
    defaultCourseId INT          NULL,
    isAvailable     BIT          NOT NULL CONSTRAINT DF_MENU_ITEM_isAvailable DEFAULT (1),

    CONSTRAINT PK_MENU_ITEM PRIMARY KEY (entryId),
    CONSTRAINT FK_MENU_ITEM_MENU_ENTRY
        FOREIGN KEY (entryId) REFERENCES dbo.MENU_ENTRY (entryId),
    CONSTRAINT FK_MENU_ITEM_COURSE
        FOREIGN KEY (defaultCourseId) REFERENCES dbo.COURSE (courseId),
    CONSTRAINT CK_MENU_ITEM_basePrice CHECK (basePrice >= 0)
);
GO

-- ==================================================================
-- Source: database/src/tables/02_menu/AddOn.sql
-- ==================================================================
-- ADD_ON: subtype of MENU_ENTRY (a modifier under an item, e.g. Cheese).
-- Level 3: points to MENU_ENTRY.
CREATE TABLE dbo.ADD_ON (
    entryId    INT          NOT NULL,
    addOnPrice DECIMAL(8,2) NOT NULL,

    CONSTRAINT PK_ADD_ON PRIMARY KEY (entryId),
    CONSTRAINT FK_ADD_ON_MENU_ENTRY
        FOREIGN KEY (entryId) REFERENCES dbo.MENU_ENTRY (entryId),
    CONSTRAINT CK_ADD_ON_addOnPrice CHECK (addOnPrice >= 0)
);
GO

-- ==================================================================
-- Source: database/src/indexes/UX_MenuEntry_SingleRoot.sql
-- ==================================================================
-- The menu tree has exactly one root: at most one MENU_ENTRY with no parent.
-- A filtered unique index allows only one row where parentEntryId IS NULL.
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE UNIQUE INDEX UX_MENU_ENTRY_single_root
    ON dbo.MENU_ENTRY (parentEntryId)
    WHERE parentEntryId IS NULL;
GO

-- ==================================================================
-- Source: database/src/indexes/UX_Shift_SingleOpen.sql
-- ==================================================================
-- Only one shift can be open at a time: at most one SHIFT with closedAt IS NULL.
-- Closing a shift and opening the next must close the old one first.
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE UNIQUE INDEX UX_SHIFT_single_open
    ON dbo.SHIFT (closedAt)
    WHERE closedAt IS NULL;
GO
